List<int> parseMusic(String musicString) {
  final List<int> result = [];
  int i = 0;
  while (i < musicString.length) {
    if (musicString[i] == ' ') {
      i++;
      continue;
    }

    int noteValue = 0;
    bool isSharp = false;
    String noteName = '';

    // Parse the note name
    switch (musicString[i]) {
      case 'A':
        noteName = 'A';
        break;
      case 'B':
        noteName = 'B';
        break;
      case 'C':
        noteName = 'C';
        break;
      case 'D':
        noteName = 'D';
        break;
      case 'E':
        noteName = 'E';
        break;
      case 'F':
        noteName = 'F';
        break;
      case 'G':
        noteName = 'G';
        break;
      default:
        throw FormatException('Invalid note name');
    }

    i++;

    // Check for sharp or flat
    if (i < musicString.length && (musicString[i] == '#' || musicString[i] == ',')) {
      isSharp = musicString[i] == '#';
      i++;
    }

    // Parse the duration value
    while (i < musicString.length && musicString[i].codeUnitAt(0).isDigit()) {
      noteValue = noteValue * 10 + (musicString[i].codeUnitAt(0) - '0'.codeUnitAt(0));
      i++;
    }

    // Convert to MIDI note number
    int midiNote = 0;
    switch (noteName) {
      case 'C': 
        midiNote = 24; 
        break;
      case 'D': 
        midiNote = 26; 
        break;
      case 'E': 
        midiNote = 28; 
        break;
      case 'F': 
        midiNote = 29; 
        break;
      case 'G': 
        midiNote = 31; 
        break;
      case 'A': 
        midiNote = 33; 
        break;
      case 'B': 
        midiNote = 35; 
        break;
      default:
        throw FormatException('Unknown note name $noteName');
    }

    // Apply sharp/flat adjustment
    if (isSharp) {
      midiNote += 1;
    } else if (!isSharp && musicString[i-1] == ',') {
      midiNote -= 1;
    }

    // Adjust based on duration value
    int totalDuration = 0;
    for (int j = 0; j < noteValue; j++) {
      totalDuration += 1 << (j % 4);
    }

    result.add(midiNote);
    result.add(totalDuration);
  }

  return result;
}
