int smallestChange(List<int> arr) {
  int n = arr.length;
  if (n == 0) return 0;

  int leftSum = 0, rightSum = 0;
  for (int i = 0; i < n; i++) {
    leftSum += arr[i];
    rightSum += arr[n - 1 - i];
  }

