  final List<String> result = [];
  int i = 0;
  while (i < s.length) {
    // Find the longest prefix of the remaining string that is a permutation
    // of some substring in the original string.
    int j = i + 1;
    int maxLen = 0;
    String currentSubstring = '';
    while (j <= s.length) {
      var substr = s.substring(i, j);
      if (_isPermutationOfOriginal(substr)) {
        currentSubstring = substr;
        maxLen = j - i;
      } else {
        break;
      }
      j++;
    }

    result.add(currentSubstring);
    i += maxLen;
  }
  return result.join('');
}

bool _isPermutationOfOriginal(String substr) {
  final Set<int> seen = {};
  for (int k = 0; k < substr.length; k++) {
