import 'dart:math';

int chooseNum(int x, int y) {
  if (x >= y) return x;
  final xor = x ^ y;
  final bits = xor.bitCount;
  final shift = bits - 1;
  final mask = (1 << shift) & xor;
  var result = y ^ mask;
  while ((result & mask) == 0) {
    result ^= mask;
    mask >>= 1;
  }
  return result;
}
```

