List<int> evenOddPalindrome(int n) {
  List<int> result = [];
  int number = n;

  while (number > 0) {
    result.add(number % 10);
    number ~/= 10;
  }

  int length = result.length;
  for (int i = 0; i < length / 2; i++) {
    if (result[i] != result[length - 1 - i]) {
      return null;
    }
  }

  bool isEvenLength = length % 2 == 0;
  int halfLength = isEvenLength ? length ~/ 2 : (length - 1) ~/ 2;

  int middleIndex = isEvenLength ? halfLength : halfLength + 1;
  int leftSide = 0, rightSide = 0;

  for (int i = 0; i < halfLength; i++) {
    leftSide = leftSide * 10 + result[i];
    rightSide = rightSide * 10 + result[length - 1 - i];
  }

  if (!isEvenLength) {
    middleIndex = halfLength;
    int midValue = result[middleIndex];

    // Check if the middle value is odd or even
    if (midValue % 2 == 0) {
      leftSide = leftSide * 10 + midValue;
    } else {
      rightSide = rightSide * 10 + midValue;
    }
  }

  int difference = abs(leftSide - rightSide);
  return [difference];
}
