List<int> evenOddPalindrome(int n) {
  List<int> digits = [];
  int temp = n;

  // Extract the digits of n
  while (temp > 0) {
    digits.add(temp % 10);
    temp ~/= 10;
  }

  // Reverse the list to get least significant digit first
  digits.reversed;

  for (int i = 0; i < digits.length / 2; i++) {
    if (digits[i] != digits[digits.length - 1 - i]) {
      return [];
    }
  }

  bool isEvenLength = digits.length % 2 == 0;
  int midIndex = isEvenLength ? digits.length ~/ 2 : digits.length ~/ 2;

  int middleDigit = isEvenLength ? 0 : digits[midIndex];

  // If length is odd, we can choose any value from 0-9 as the middle digit
  // But since it's a palindrome, this choice doesn't affect the result.
  // So, let's just pick 5 for simplicity.

  int newMiddleValue = isEvenLength ? 4 : 5;

  // Create a new list with the middle part replaced by newMiddleValue
  List<int> newDigits = List.from(digits);

  if (isEvenLength) {
    newDigits[midIndex] = newMiddleValue;
    newDigits[midIndex + 1] = newMiddleValue;
  } else {
    newDigits[midIndex] = newMiddleValue;
  }

  // Convert back to number and return as list of digits
  int num = 0;
  for (int d in newDigits) {
    num = num * 10 + d;
  }
  return [num];
}
