import 'dart:math';

String wordsInSentence(String sentence) {
  if (sentence.isEmpty) return '';

  final List<String> words = [];
  int wordStartIndex = -1;
  bool isInsideWord = false;

  for (int i = 0; i < sentence.length; i++) {
    final char = sentence[i];

    if (char.isLetterOrDigit && !isInsideWord) {
      isInsideWord = true;
      wordStartIndex = i;
    } else if (!char.isLetterOrDigit && isInsideWord) {
      isInsideWord = false;
      words.add(sentence.substring(wordStartIndex, i));
    }
  }

  // Handle the last word if the sentence ends with a letter or digit
  if (isInsideWord) {
    words.add(sentence.substring(wordStartIndex, sentence.length));
  }

  return words.join(' ');
}
